"use client";
import React from 'react';

const PaymentPartners = () => {
  const partners = [
    {
      name: "eSewa",
      logo: "https://blog.esewa.com.np/wp-content/uploads/2022/06/esewa-logo.png",
      link: "https://esewa.com.np"
    },
    {
      name: "Khalti",
      logo: "https://khalti.com/static/khalti-logo.png",
      link: "https://khalti.com"
    },
    {
      name: "Connect IPS",
      logo: "https://www.connectips.com/images/connectips-logo.png",
      link: "https://www.connectips.com"
    }
  ];

  return (
    <section style={styles.section}>
      <div style={styles.container}>
        <h2 style={styles.heading}>Our Digital Payment Partners</h2>
        <div style={styles.divider}></div>
        <p style={styles.subText}>
          Seamlessly pay your installments or save through our integrated digital partners.
        </p>
        
        <div style={styles.grid}>
          {partners.map((partner, index) => (
            <a 
              key={index} 
              href={partner.link} 
              target="_blank" 
              rel="noopener noreferrer" 
              style={styles.card}
            >
              <img 
                src={partner.logo} 
                alt={partner.name} 
                style={styles.logo} 
              />
            </a>
          ))}
        </div>
      </div>
    </section>
  );
};

const styles = {
  section: {
    backgroundColor: "#ffffff",
    padding: "60px 20px",
    textAlign: "center",
  },
  container: {
    maxWidth: "1100px",
    margin: "0 auto",
  },
  heading: {
    color: "#003366", // Corporate Blue
    fontSize: "2rem",
    marginBottom: "10px",
  },
  divider: {
    width: "60px",
    height: "4px",
    backgroundColor: "#28a745", // Growth Green
    margin: "0 auto 20px",
    borderRadius: "2px",
  },
  subText: {
    color: "#666",
    marginBottom: "40px",
  },
  grid: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    flexWrap: "wrap",
    gap: "40px",
  },
  card: {
    backgroundColor: "#f4f7f9",
    padding: "20px",
    borderRadius: "10px",
    width: "200px",
    height: "100px",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    transition: "transform 0.3s ease, box-shadow 0.3s ease",
    cursor: "pointer",
    border: "1px solid #e1e8ed",
  },
  logo: {
    maxWidth: "100%",
    maxHeight: "60px",
    filter: "grayscale(20%)",
  }
};

export default PaymentPartners;
